// Source: net.minecraft.world.item.trading.VillagerTrades / TradeSet (26.2)
//
// data/villager_trades.json is generated by scripts/build-villager-trades.mjs from
// the vanilla trade_set -> villager_trade tag -> trade JSON chain. Each level has
// an `amount` (vanilla trade_set amount, normally 2) and a pool of trade rows;
// a villager draws `amount` distinct rows when it reaches that level.

import type { ItemRegistry } from '../../item/Item.js';
import { MerchantOffer, type TradeSpec } from '../../item/trading/MerchantOffer.js';
import type { RandomSource } from '../../../core/Random.js';

interface LevelTrades {
  amount: number;
  trades: TradeSpec[];
}
interface ProfessionTrades {
  levels: LevelTrades[];
}
export type VillagerTradeData = Record<string, ProfessionTrades>;

export class VillagerTrades {
  /** Loaded by Game; villagers read it when they claim a job site or level up. */
  static current: VillagerTrades | null = null;

  constructor(readonly data: VillagerTradeData) {}

  static async load(base = '/data'): Promise<VillagerTrades> {
    try {
      const res = await fetch(`${base}/villager_trades.json`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const manager = new VillagerTrades(await res.json() as VillagerTradeData);
      VillagerTrades.current = manager;
      return manager;
    } catch (err) {
      console.warn('[trades] villager_trades.json unavailable:', err);
      const empty = new VillagerTrades({});
      VillagerTrades.current = empty;
      return empty;
    }
  }

  hasProfession(profession: string): boolean {
    return !!this.data[profession];
  }

  levelCount(profession: string): number {
    return this.data[profession]?.levels.length ?? 0;
  }

  /** AbstractVillager.addOffersFromTradeSet: pick `amount` distinct rows. */
  createOffers(profession: string, level: number, registry: ItemRegistry, random: RandomSource): MerchantOffer[] {
    const entry = this.data[profession]?.levels[level - 1];
    if (!entry) return [];
    const pool = entry.trades.slice();
    const count = Math.min(entry.amount, pool.length);
    const offers: MerchantOffer[] = [];
    for (let i = 0; i < count; i++) {
      const index = random.nextInt(pool.length);
      const spec = pool.splice(index, 1)[0];
      offers.push(new MerchantOffer(spec, registry, random, level));
    }
    return offers;
  }
}
